inline flight::types::PlatformKind parse_user_agent_kind(flight::types::PlatformName name) {
  if (((name == flight::String("ios")) || (name == flight::String("android")))) {
    return flight::String("mobile");
  }
  return flight::String("web");
}

inline flight::types::PlatformName parse_user_agent_name(flight::String ua) {
  if (flight::RegExp(flight::String("android"), flight::String("i")).test(ua)) {
    return flight::String("android");
  }
  if (flight::RegExp(flight::String("iphone|ipad|ipod"), flight::String("i")).test(ua)) {
    return flight::String("ios");
  }
  if (flight::RegExp(flight::String("win"), flight::String("i")).test(ua)) {
    return flight::String("windows");
  }
  if (flight::RegExp(flight::String("mac"), flight::String("i")).test(ua)) {
    return flight::String("macos");
  }
  if (flight::RegExp(flight::String("linux"), flight::String("i")).test(ua)) {
    return flight::String("linux");
  }
  return flight::String("web");
}

inline double parse_user_agent_pointer_width(flight::String arch) {
  if (((arch == flight::String("x64")) || (arch == flight::String("arm64")))) {
    return 64.0;
  }
  if (((arch == flight::String("x86")) || (arch == flight::String("arm")))) {
    return 32.0;
  }
  return -1.0;
}

